import {fireLevel} from './fire-status.js';
import {assessMeans,meansPanel} from './means-assessment.js';
import {extricationStatus,rescueTruck} from './extrication.js';
import {revealElevator,elevatorStatus} from './elevator-rescue.js';
import {formatRadio,conciseRadio} from './radio-voice.js';
import {elevatedStatus} from './aerial-operations.js';
import {buildingActionsPanel} from './building-actions.js';
import {playerLabel,escapeHtml} from './player-profile.js';
import {inspectFire} from './incident-catalog.js';
import {waterStatus} from './water-rescue.js';
import {initComplication,tickComplication,complicationPanel} from './incident-events.js';
export const PRIORITIES={balanced:'Action équilibrée',rescue:'Priorité aux victimes',contain:'Limiter la propagation'};
export function initIncident(c){initComplication(c);c.radio=[];c.reinforcementAlerts=[];c.reconProgress=0;c.reconComplete=false;c.priority='balanced';if(c.type==='INC'){c.fireLoad=1;c.spread=0;c.fireLevel=1;}}
export function applyFireRegrowth(c,active,minutes,forest=false){
 if(active||!c.reconComplete||c.fireContained||c.status==='closed'||!(c.progress>0)||c.progress>=1)return 0;
 const before=c.progress,foamProtection=Math.max(.2,1-(c.foamCoverage||0)*.8),rate=(forest?.003:.0018)*(1+(c.spread||0)*.7)*foamProtection;
 c.progress=Math.max(0,c.progress-minutes*rate);
 return before-c.progress;
}
export function radio(c,minute,sender,message,emit,urgent=false){c.radio??=[];const need=/Renfort (?:VSR ou )?FPTSR demandé/.test(message)?'extrication':/Renfort EPA demandé/.test(message)?'aerial':/VSAV supplémentaires/.test(message)?'vsav':/infirmier conseillé/.test(message)?'nurse':/plongeurs et bateau nécessaires/.test(message)?'divers':null;const transmission=formatRadio(c.id,sender,message),entry={minute,sender,message,transmission,urgent,need};c.radio.push(entry);if(urgent&&/renfort|conseillé|plongeurs et bateau nécessaires|citerne vide|VSAV supplémentaires/i.test(message)){c.reinforcementAlerts??=[];if(!c.reinforcementAlerts.some(r=>r.message===message))c.reinforcementAlerts.push(entry);}if(urgent)c.radioAlert=entry;if(c.radio.length>12)c.radio.shift();emit(`Radio · ${transmission}`,urgent);return entry;}
export function situation(c){if(!c.reconComplete)return 'Reconnaissance en cours, bilan à confirmer.';if(c.elevator)return elevatorStatus(c);if(c.extrication)return extricationStatus(c);if(c.inspection&&c.fireConfirmed!==true)return c.fireConfirmed===false?'Aucun incendie constaté. Contrôle final en cours.':'Levée de doute : attendre la vérification par un fourgon.';return c.type==='INC'?`Foyer ${c.fireLevel===3?'étendu':c.fireLevel===2?'en propagation':'localisé'}. ${Math.round((c.progress||0)*100)} % maîtrisé.${c.complication?(c.complication.status==='resolved'?' Personne mise en sécurité.':' Personne bloquée à l’étage · '+(c.complication.choice?'sauvetage engagé.':'ordre attendu.')):''}`:c.victimCount?`${c.victimCount} victime(s), ${c.patients.filter(p=>p.severe).length} grave(s), ${c.victimCount-c.evacuated} encore sur place.`:`${c.name} : ${Math.round((c.progress||0)*100)} % réalisé.`;}
export function tickCommand(state,engines,dt,emit){const minutes=dt*state.speed/60;for(const c of state.calls){if(c.status==='closed')continue;const mobilized=engines.filter(e=>e.call===c.id&&['scene','enroute','departing'].includes(e.status));c.reinforcementAlerts=(c.reinforcementAlerts||[]).filter(a=>a.need==='extrication'?!mobilized.some(rescueTruck)&&!c.extrication?.done:a.need==='vsav'?mobilized.filter(e=>e.kind==='VSAV').length<c.victimCount-c.evacuated:a.need==='nurse'?!mobilized.some(e=>e.kind==='VLI')&&c.patients?.some(p=>p.severe&&!p.evacuated&&!p.nursingComplete):a.need==='aerial'?!mobilized.some(e=>e.kind==='EPA')&&!c.elevatedRescue?.done:a.need==='divers'?!mobilized.some(e=>e.kind==='VPL')&&!c.nautical?.done:true);const units=engines.filter(e=>e.call===c.id&&e.status==='scene'),officer=units.some(e=>e.kind==='VLCG');if(units.length&&!c.reconComplete){c.reconProgress=Math.min(1,c.reconProgress+minutes/(officer?2:4));if(c.reconProgress>=1){c.reconComplete=true;revealElevator(c);c.victimsKnown=!!c.victimCount;if(c.victimCount>1){c.finishBudget+=15*(c.victimCount-1);radio(c,state.minute,'Centre','Objectif de prise en charge ajusté au bilan : '+c.victimCount+' victimes.',emit);}radio(c,state.minute,officer?playerLabel(state.playerProfile):units[0].id,situation(c),emit);}}tickComplication(c,engines,minutes,state.minute,(sender,message,urgent)=>{const entry=radio(c,state.minute,sender,message,emit,urgent);if(urgent)entry.kind='decision';},!state.calls.some(other=>other!==c&&other.complication&&other.complication.status!=='resolved'));if(c.inspection&&units.some(e=>e.capacity)&&inspectFire(c)){radio(c,state.minute,units.find(e=>e.capacity).id,c.fireConfirmed?'Feu confirmé à la reconnaissance. Établissez les lances et l’alimentation.':'Aucun feu constaté. Vérifications en cours, pas de lance nécessaire.',emit);}if(c.type==='INC'&&c.progress<1&&(!c.inspection||c.fireConfirmed===true)){const active=units.some(e=>e.flow>0);const forest=c.requires==='CCF'||['forest','vegetation'].includes(c.scene);const suppression=units.reduce((n,e)=>n+(e.flow||0),0);applyFireRegrowth(c,active,minutes,forest);const growth=(forest?(suppression>=500?.002:suppression>0?.007:.015):(active?.0008:.003))*(c.buildingActions?.electricity==='off'&&c.buildingActions?.gas!=='on'?.85:1);const containment=c.priority==='contain'?.45:1;c.spread=Math.max(0,Math.min(1.5,c.spread+minutes*(active?growth*(1-c.progress)-c.progress*.003:growth)*containment));c.fireLoad=1+c.spread;c.fireLevel=fireLevel(c);if(c.reconComplete&&c.fireLevel!==(c.reportedLevel||1)){const rising=c.fireLevel>(c.reportedLevel||1);c.reportedLevel=c.fireLevel;radio(c,state.minute,units[0]?.id||'Centre',rising?`Propagation du feu — niveau ${c.fireLevel}. Renfort incendie conseillé.`:`Intensité en baisse — niveau ${c.fireLevel}.`,emit,rising);}}if(c.waterRescue&&c.reconComplete&&!c.nautical.done&&!engines.some(e=>e.kind==='VPL'&&e.call===c.id)&&!c.diversRequested){c.diversRequested=true;radio(c,state.minute,units[0]?.id||'Centre','Victime dans l’étang : plongeurs et bateau nécessaires. Engagez VPL 1.',emit,true);}if(c.reconComplete&&c.patients?.some(p=>p.severe&&!p.evacuated&&!p.nursingComplete)&&!c.nurseRequested&&!engines.some(e=>e.kind==='VLI'&&e.call===c.id)){c.nurseRequested=true;radio(c,state.minute,units[0]?.id||'Centre','Victime grave : soutien infirmier conseillé. Engagez le VLI si disponible.',emit,true);}if(c.reconComplete&&c.victimCount){const available=engines.filter(e=>e.call===c.id&&e.kind==='VSAV'&&['scene','departing','enroute'].includes(e.status)).length,remaining=c.victimCount-c.evacuated;if(remaining<=available)c.reinforcementReported=false;if(remaining>available&&!c.reinforcementReported){c.reinforcementReported=true;radio(c,state.minute,units[0]?.id||'Centre',`${remaining} victime(s) à évacuer pour ${available} VSAV engagé(s). Demande de VSAV supplémentaires.`,emit,true);}}}}
export function reportMeans(state,engines,emit){for(const c of state.calls){if(!c.reconComplete||c.status==='closed'||c.siteCompletedAt!=null)continue;const a=assessMeans(c,engines),key=a.key+':'+a.detail;if(c.meansReport===key)continue;const unit=engines.find(e=>e.call===c.id&&e.status==='scene');if(!unit)continue;c.meansReport=key;radio(c,state.minute,unit.id,a.label+'.'+(a.detail?' '+a.detail+'.':''),emit);}}
export function commandPanel(c,engines){if(c.siteCompletedAt!=null)return '';const cg=engines.find(e=>e.kind==='VLCG'),here=cg?.call===c.id&&cg.status==='scene';return `<section class="commandPanel compactCommand"><div class="commandToolbar"><span title="Reconnaissance : ${Math.round(c.reconProgress*100)} %">${c.reconComplete?'✓ Bilan établi':`⌕ Recon. ${Math.round(c.reconProgress*100)} %`}</span><button data-radio-report title="Demander un bilan radio" aria-label="Demander un bilan radio">📻 Bilan</button>${cg&&['ready','returning','idle'].includes(cg.status)?'<button data-captain-go title="Me rendre sur place en VLCG">↗ Partir</button>':`<small>★ ${here?'Sur place':'Engagé'}</small>`}</div>${c.waterRescue?`<p class="reconSummary">⚓ ${waterStatus(c)}</p>`:''}${c.elevatedRescue&&c.reconComplete?`<p class="reconSummary">${escapeHtml(elevatedStatus(c))}</p>`:''}${c.elevator&&c.reconComplete?`<p class="reconSummary">${escapeHtml(elevatorStatus(c))}</p>`:''}${c.extrication&&c.reconComplete?`<p class="reconSummary">${escapeHtml(extricationStatus(c))}</p>`:''}${meansPanel(c,engines)}${buildingActionsPanel(c,engines)}${complicationPanel(c,engines)}</section>`;}
export function radioPanel(c){const entries=radioEntries(c);return `<details class="radioDetails" ${c.radioExpanded?'open':''}><summary>📻 Messages radio (${entries.length})</summary><div class="radioFeed">${entries.slice().reverse().map(r=>`<p class="${r.urgent?'radioUrgent':''}">${escapeHtml(r.transmission||r.message)}</p>`).join('')||'<p>En attente du premier bilan.</p>'}</div></details>`;}

function radioEntries(c){return(c.events||c.radio).filter(r=>!(c.reinforcementAlerts||[]).some(a=>r.message.includes(a.message)||r.transmission===a.transmission||r.message.includes(a.transmission||a.message)));}
export function reinforcementPanel(c){return c.reinforcementAlerts?.length?`<section class="reinforcementAlert incidentReinforcement" role="status"><b>⚠ Renfort demandé</b>${c.reinforcementAlerts.map(a=>`<p>${escapeHtml(a.sender)} : ${escapeHtml(a.message)}</p>`).join('')}<button data-ack-radio="${c.id}">Bien reçu</button></section>`:'';}
